package com.ekayn.api.api; import com.ekayn.api.api.ApiModels.*; import com.ekayn.api.model.*; import com.ekayn.api.service.OrderService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')") public class AdminController { private final OrderService service; @GetMapping("/orders") public List<AdminOrderResponse> orders(){return service.all();} @PatchMapping("/orders/{id}/delivery") public AdminOrderResponse delivery(@PathVariable UUID id,@Valid @RequestBody DeliveryUpdate update){return service.update(id,update);} }
